const query = String($('When Called By Agent').first().json.query || '').toLowerCase();
const stop = new Set(['the','a','an','and','or','of','to','for','in','on','do','you','your','is','are','what','how','much','i','my','can','we','it','me','with','at','does']);
const words = query.split(/[^a-z0-9]+/).filter(w => w.length > 1 && !stop.has(w));
const rows = $input.all().map(i => i.json).filter(r => r && (r.content || r.document_name));
const scored = rows.map(r => {
  const hay = [r.document_name, r.topic, r.content].join(' ').toLowerCase();
  const score = words.reduce((s, w) => s + (hay.includes(w) ? 1 : 0), 0);
  return { document_name: r.document_name, topic: r.topic, content: r.content, score };
}).filter(r => r.score > 0).sort((a, b) => b.score - a.score).slice(0, 5);
if (scored.length === 0) {
  return [{ json: { results: [], message: 'No results found in the knowledge base for this query.' } }];
}
return [{ json: { results: scored.map(({ score, ...rest }) => rest), message: scored.length + ' matching document(s) found.' } }];
